import json, os, tempfile, threading
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
from ledger import crypto
from ledger.light_client import advance
from ledger.models import Block, Transaction
from ledger.store import LedgerStore

NOW = 1_000_000_000
FUTURE = NOW + 10_000
key = Ed25519PrivateKey.generate()
pub = key.public_key().public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw).hex()
genesis = LedgerStore.create_genesis()
anchor = {"height": 0, "block_hash": genesis.block_hash}
txs, blocks, prev = [], [], genesis.block_hash
for i, amount in enumerate(range(10, 30), start=1):
    tx = Transaction(pub, "b"*64, amount, key.sign(crypto.canonical_message(pub, "b"*64, amount)).hex())
    b = Block.create(i, prev, [tx]); txs.append(tx); blocks.append(b); prev = b.block_hash
trust = {"allowlist": {"node-plain": FUTURE}}
ORDER = ["source","request_id","mode","expires_at","anchor","blocks","tip","attestation"]
def page(anchor, blks, idx):
    last = blks[-1]
    tip = {"tip_hash": last.block_hash, "height": last.height, "length": anchor["height"]+1+len(blks), "status": last.status}
    doc = {"source":"node-plain","request_id":f"r{idx}","mode":"plain","expires_at":FUTURE,
           "anchor":dict(anchor),"blocks":[b.to_dict() for b in blks],"tip":tip,"attestation":None}
    return {k: doc[k] for k in ORDER}

tmp = tempfile.mkdtemp(); path = os.path.join(tmp, "cp.json")
# 10 threads each advancing one block sequentially-chained; lock must keep generations dense 1..10
results = []
def worker(i):
    a = {"height": i, "block_hash": (genesis.block_hash if i == 0 else blocks[i-1].block_hash)}
    r = advance(path, [page(a, [blocks[i]], i)], trust, None, NOW)
    results.append(r)
threads = [threading.Thread(target=worker, args=(i,)) for i in range(10)]
for t in threads: t.start()
for t in threads: t.join()
# With all racing, some may fail with integrity (expected anchor moved) — that's fine;
# run them again until all succeed, then check generations are dense.
for i in range(10):
    a = {"height": i, "block_hash": (genesis.block_hash if i == 0 else blocks[i-1].block_hash)}
    r = advance(path, [page(a, [blocks[i]], i)], trust, None, NOW)
state = json.load(open(path))
print("final generation:", state["generation"])
print("tip height:", state["tip"]["height"])
print("file ends with single newline:", open(path,'rb').read().endswith(b'}\n') or open(path,'rb').read().endswith(b'"\n') or open(path,'rb').read()[-2:-1] != b'\n')
EOF
